s = input().strip()
pairs = {')': '(', ']': '[', '}': '{'}
stack = []
ok = True
for ch in s:
    if ch in '([{':
        stack.append(ch)
    elif not stack or stack.pop() != pairs[ch]:
        ok = False
        break
print("Valid" if ok and not stack else "Invalid")

nums = list(map(int, input().split()))
freq = {}
for x in nums:
    freq[x] = freq.get(x, 0) + 1
best = max(freq.values())
print(min(x for x in freq if freq[x] == best))

s = input()
freq = {}
for ch in s:
    if ch != ' ':
        freq[ch] = freq.get(ch, 0) + 1
dups = sorted(ch for ch in freq if freq[ch] > 1)
if not dups:
    print("No duplicates")
else:
    for ch in dups:
        print(f"{ch}: {freq[ch]}")

