if op == '/' and b == 0:
    print("Error: Division by zero")
else:
    if op == '+':
        r = a + b
    elif op == '-':
        r = a - b
    elif op == '*':
        r = a * b
    else:
        r = a / b
    print(f"{r + 0.0:.2f}")

